/** The plot lines as a sketch: the DXF read in metres, welded into one loop. */
export function rmuhSiteSketch() {
  const { drawing } = dxfDrawing(readDXF(RMUH_SITE_DXF, { askUnits: () => "m" }));
  return weld({ elements: drawing.elements.map(({ layer, ...e }) => e), constraints: [], dims: [] });
}
export function buildRmuhSample() {
  const doc = newDocument("D1 RMUH - Qiddiya Downtown Retail Mixed-Use Hub"), ed = new Editor(doc);
  const add = element => { const r = ed.apply({ op: "add", element }); if (!r.ok) throw new Error(`${element.type}: ${r.error}`); return r.id; };
  add({ id: "L0", type: "Level", name: "Ground", args: { name: "Ground", elevation: 0 } });
  add({ id: "L1", type: "Level", name: "Level 1", args: { name: "Level 1", elevation: 6500 } });
  add({ id: "V-SITE", type: "PlanView", name: "Site Plan", args: { level: { ref: "L0" }, scale: 2000, viewRange: { top: 250000, cut: 1200, bottom: 0, depth: 0 }, detailLevel: "Coarse", style: { ref: "VS-PRESENTATION" }, clip: { rect: null, visible: false, active: false } } });
  add({ id: "V-L1", type: "PlanView", name: "Level 1 Plan", args: { level: { ref: "L1" }, scale: 1000, viewRange: { top: 5000, cut: 1200, bottom: 0, depth: 0 }, detailLevel: "Coarse", style: { ref: "VS-CONSTRUCTION" }, clip: { rect: null, visible: false, active: false } } });
  add({ id: "V-3D", type: "View3D", name: "{3D}", args: { camera: { azimuth: 210, elevation: 35, target: [300000, 430000, 20000] }, scale: 2000, style: { ref: "VS-CONSTRUCTION" }, visualStyle: "Shaded" } });
  add({ id: "SITE", type: "SiteBoundary", name: "Site boundary (client plot lines)", args: { sketch: rmuhSiteSketch(), edges: {}, setback: 0, level: { ref: "L0" }, showPlanes: false, planeHeight: 120000 } });
  const prog = programFromBrief(RMUH_BRIEF);
  relaxBubbles(prog.nodes, prog.edges, 500);
  // the PUA light-rail is the primary arrival, on the south edge (the brief: may flip north)
  const entries = [{ at: [300000, 3900], dir: [0, 1] }];
  add({ id: "SG1", type: "SpaceGraph", name: "D1 RMUH brief", args: { nodes: prog.nodes, edges: prog.edges, site: { boundary: [], setbacks: [], entries, spine: null, attractors: [], area: prog.site.area, developable: prog.site.developable },
    options: { legend: (prog.legends && prog.legends.dept) || defaultLegend(prog.nodes), legends: Object.fromEntries(Object.entries(prog.legends || {}).filter(([k]) => k !== "dept")), labels: prog.labels, colourBy: "fn", mode: "auto", street: 18000, briefText: RMUH_BRIEF }, order: null, level: { ref: "L0" }, auto: true, siteBoundary: { ref: "SITE" } } });
  const b = ed.apply({ op: "sgbuild", id: "SG1" }); if (!b.ok) throw new Error(b.error);
  // the analysis on an A1 sheet, ready to print: its diagrams draw themselves from SG1 in the app
  add({ id: "SH-A001", type: "Sheet", name: "A-001 Brief Analysis", args: { number: "A-001", sheetName: "Brief Analysis", size: "A1", orientation: "landscape", viewports: [], revision: "P01",
    diagrams: diagramSheetLayout().map(d => Object.assign(d, { diagram: Object.assign({ sg: "SG1" }, d.diagram) })) } });
  doc.meta.brief = { source: "D1_RMUH_Massing_Brief_for_AI.txt", report: prog.report };
  ed.undoStack.length = 0;
  return doc;
}
